import{_ as o,c as n,o as r,j as s,Y as i,t as l}from"./chunks/framework.D-NV0Bun.js";const d=JSON.parse('{"title":"git-mergetool | x-cmd man (git man1) | Run merge conflict resolution tools to resolve merge","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-mergetool - Run merge conflict resolution tools to resolve merge","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-mergetool | x-cmd man (git man1) | Run merge conflict resolution tools to resolve merge"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-mergetool - Run merge conflict resolution tools to resolve merge"}]]},"headers":[],"params":{"isMan":true,"man":"git-mergetool","category":"git man1","desc":"Run merge conflict resolution tools to resolve merge"},"relativePath":"git/man1/git-mergetool.md","filePath":"git/man1/[man].md"}'),a={name:"git/man1/git-mergetool.md"},g={class:"visually-hidden"};function u(t,e,p,c,h,m){return r(),n("div",null,[s("h1",g,l(t.$params.man),1),e[0]||(e[0]=i(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-mergetool - Run merge conflict resolution tools to resolve merge conflicts</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mergetool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--tool=&lt;tool&gt;] [-y </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --[no-]prompt] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Use <strong>git mergetool</strong> to run one of several merge utilities to resolve merge conflicts. It is typically run after <em>git merge</em>.</p><p>If one or more &lt;file&gt; parameters are given, the merge tool program will be run to resolve differences on each file (skipping those without conflicts). Specifying a directory will include all unresolved files in that path. If no &lt;file&gt; names are specified, <em>git mergetool</em> will run the merge tool program on every file with merge conflicts.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-t &lt;tool&gt;, --tool=&lt;tool&gt;</p><blockquote><p>Use the merge resolution program specified by &lt;tool&gt;. Valid values include emerge, gvimdiff, kdiff3, meld, vimdiff, and tortoisemerge. Run <strong>git mergetool --tool-help</strong> for the list of valid &lt;tool&gt; settings.</p><p>If a merge resolution program is not specified, <em>git mergetool</em> will use the configuration variable <strong>merge.tool</strong>. If the configuration variable <strong>merge.tool</strong> is not set, <em>git mergetool</em> will pick a suitable default.</p><p>You can explicitly provide a full path to the tool by setting the configuration variable <strong>mergetool.&lt;tool&gt;.path</strong>. For example, you can configure the absolute path to kdiff3 by setting <strong>mergetool.kdiff3.path</strong>. Otherwise, <em>git mergetool</em> assumes the tool is available in PATH.</p><p>Instead of running one of the known merge tool programs, <em>git mergetool</em> can be customized to run an alternative program by specifying the command line to invoke in a configuration variable <strong>mergetool.&lt;tool&gt;.cmd</strong>.</p><p>When <em>git mergetool</em> is invoked with this tool (either through the <strong>-t</strong> or <strong>--tool</strong> option or the <strong>merge.tool</strong> configuration variable) the configured command line will be invoked with <strong>$BASE</strong> set to the name of a temporary file containing the common base for the merge, if available; <strong>$LOCAL</strong> set to the name of a temporary file containing the contents of the file on the current branch; <strong>$REMOTE</strong> set to the name of a temporary file containing the contents of the file to be merged, and <strong>$MERGED</strong> set to the name of the file to which the merge tool should write the result of the merge resolution.</p><p>If the custom merge tool correctly indicates the success of a merge resolution with its exit code, then the configuration variable <strong>mergetool.&lt;tool&gt;.trustExitCode</strong> can be set to <strong>true</strong>. Otherwise, <em>git mergetool</em> will prompt the user to indicate the success of the resolution after the custom tool has exited.</p></blockquote><p>--tool-help</p><blockquote><p>Print a list of merge tools that may be used with <strong>--tool</strong>.</p></blockquote><p>-y, --no-prompt</p><blockquote><p>Don&#39;t prompt before each invocation of the merge resolution program. This is the default if the merge resolution program is explicitly specified with the <strong>--tool</strong> option or with the <strong>merge.tool</strong> configuration variable.</p></blockquote><p>--prompt</p><blockquote><p>Prompt before each invocation of the merge resolution program to give the user a chance to skip the path.</p></blockquote><p>-g, --gui</p><blockquote><p>When <em>git-mergetool</em> is invoked with the <strong>-g</strong> or <strong>--gui</strong> option the default merge tool will be read from the configured <strong>merge.guitool</strong> variable instead of <strong>merge.tool</strong>. If <strong>merge.guitool</strong> is not set, we will fallback to the tool configured under <strong>merge.tool</strong>.</p></blockquote><p>--no-gui</p><blockquote><p>This overrides a previous <strong>-g</strong> or <strong>--gui</strong> setting and reads the default merge tool will be read from the configured <strong>merge.tool</strong> variable.</p></blockquote><p>-O&lt;orderfile&gt;</p><blockquote><p>Process files in the order specified in the &lt;orderfile&gt;, which has one shell glob pattern per line. This overrides the <strong>diff.orderFile</strong> configuration variable (see <strong>git-config</strong>(1)). To cancel <strong>diff.orderFile</strong>, use <strong>-O/dev/null</strong>.</p></blockquote><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>Everything below this line in this section is selectively included from the <strong>git-config</strong>(1) documentation. The content is the same as what&#39;s found there:</p><p>mergetool.&lt;tool&gt;.path</p><blockquote><p>Override the path for the given tool. This is useful in case your tool is not in the PATH.</p></blockquote><p>mergetool.&lt;tool&gt;.cmd</p><blockquote><p>Specify the command to invoke the specified merge tool. The specified command is evaluated in shell with the following variables available: <em>BASE</em> is the name of a temporary file containing the common base of the files to be merged, if available; <em>LOCAL</em> is the name of a temporary file containing the contents of the file on the current branch; <em>REMOTE</em> is the name of a temporary file containing the contents of the file from the branch being merged; <em>MERGED</em> contains the name of the file to which the merge tool should write the results of a successful merge.</p></blockquote><p>mergetool.&lt;tool&gt;.hideResolved</p><blockquote><p>Allows the user to override the global <strong>mergetool.hideResolved</strong> value for a specific tool. See <strong>mergetool.hideResolved</strong> for the full description.</p></blockquote><p>mergetool.&lt;tool&gt;.trustExitCode</p><blockquote><p>For a custom merge command, specify whether the exit code of the merge command can be used to determine whether the merge was successful. If this is not set to true then the merge target file timestamp is checked and the merge assumed to have been successful if the file has been updated, otherwise the user is prompted to indicate the success of the merge.</p></blockquote><p>mergetool.meld.hasOutput</p><blockquote><p>Older versions of <strong>meld</strong> do not support the <strong>--output</strong> option. Git will attempt to detect whether <strong>meld</strong> supports <strong>--output</strong> by inspecting the output of <strong>meld --help</strong>. Configuring <strong>mergetool.meld.hasOutput</strong> will make Git skip these checks and use the configured value instead. Setting <strong>mergetool.meld.hasOutput</strong> to <strong>true</strong> tells Git to unconditionally use the <strong>--output</strong> option, and <strong>false</strong> avoids using <strong>--output</strong>.</p></blockquote><p>mergetool.meld.useAutoMerge</p><blockquote><p>When the <strong>--auto-merge</strong> is given, meld will merge all non-conflicting parts automatically, highlight the conflicting parts and wait for user decision. Setting <strong>mergetool.meld.useAutoMerge</strong> to <strong>true</strong> tells Git to unconditionally use the <strong>--auto-merge</strong> option with <strong>meld</strong>. Setting this value to <strong>auto</strong> makes git detect whether <strong>--auto-merge</strong> is supported and will only use <strong>--auto-merge</strong> when available. A value of <strong>false</strong> avoids using <strong>--auto-merge</strong> altogether, and is the default value.</p></blockquote><p>mergetool.vimdiff.layout</p><blockquote><p>The vimdiff backend uses this variable to control how its split windows look like. Applies even if you are using Neovim (<strong>nvim</strong>) or gVim (<strong>gvim</strong>) as the merge tool. See BACKEND SPECIFIC HINTS section for details.</p></blockquote><p>mergetool.hideResolved</p><blockquote><p>During a merge Git will automatically resolve as many conflicts as possible and write the <em>MERGED</em> file containing conflict markers around any conflicts that it cannot resolve; <em>LOCAL</em> and <em>REMOTE</em> normally represent the versions of the file from before Git&#39;s conflict resolution. This flag causes <em>LOCAL</em> and <em>REMOTE</em> to be overwritten so that only the unresolved conflicts are presented to the merge tool. Can be configured per-tool via the <strong>mergetool.&lt;tool&gt;.hideResolved</strong> configuration variable. Defaults to <strong>false</strong>.</p></blockquote><p>mergetool.keepBackup</p><blockquote><p>After performing a merge, the original file with conflict markers can be saved as a file with a <strong>.orig</strong> extension. If this variable is set to <strong>false</strong> then this file is not preserved. Defaults to <strong>true</strong> (i.e. keep the backup files).</p></blockquote><p>mergetool.keepTemporaries</p><blockquote><p>When invoking a custom merge tool, Git uses a set of temporary files to pass to the tool. If the tool returns an error and this variable is set to <strong>true</strong>, then these temporary files will be preserved, otherwise they will be removed after the tool has exited. Defaults to <strong>false</strong>.</p></blockquote><p>mergetool.writeToTemp</p><blockquote><p>Git writes temporary <em>BASE</em>, <em>LOCAL</em>, and <em>REMOTE</em> versions of conflicting files in the worktree by default. Git will attempt to use a temporary directory for these files when set <strong>true</strong>. Defaults to <strong>false</strong>.</p></blockquote><p>mergetool.prompt</p><blockquote><p>Prompt before each invocation of the merge resolution program.</p></blockquote><h2 id="temporary-files" tabindex="-1">TEMPORARY FILES <a class="header-anchor" href="#temporary-files" aria-label="Permalink to &quot;TEMPORARY FILES&quot;">​</a></h2><p><strong>git mergetool</strong> creates <strong>*.orig</strong> backup files while resolving merges. These are safe to remove once a file has been merged and its <strong>git mergetool</strong> session has completed.</p><p>Setting the <strong>mergetool.keepBackup</strong> configuration variable to <strong>false</strong> causes <strong>git mergetool</strong> to automatically remove the backup as files are successfully merged.</p><h2 id="backend-specific-hints" tabindex="-1">BACKEND SPECIFIC HINTS <a class="header-anchor" href="#backend-specific-hints" aria-label="Permalink to &quot;BACKEND SPECIFIC HINTS&quot;">​</a></h2><h3 id="vimdiff" tabindex="-1">vimdiff <a class="header-anchor" href="#vimdiff" aria-label="Permalink to &quot;vimdiff&quot;">​</a></h3><br> **Description** <blockquote><p>When specifying <strong>--tool=vimdiff</strong> in <strong>git mergetool</strong> Git will open Vim with a 4 windows layout distributed in the following way:</p><blockquote><pre><code>------------------------------------------
|             |           |              |
|   LOCAL     |   BASE    |   REMOTE     |
|             |           |              |
------------------------------------------
|                                        |
|                MERGED                  |
|                                        |
------------------------------------------
</code></pre></blockquote><p><strong>LOCAL</strong>, <strong>BASE</strong> and <strong>REMOTE</strong> are read-only buffers showing the contents of the conflicting file in specific commits (&quot;commit you are merging into&quot;, &quot;common ancestor commit&quot; and &quot;commit you are merging from&quot; respectively)</p><p><strong>MERGED</strong> is a writable buffer where you have to resolve the conflicts (using the other read-only buffers as a reference). Once you are done, save and exit Vim as usual (<strong>:wq</strong>) or, if you want to abort, exit using <strong>:cq</strong>.</p></blockquote><br> **Layout configuration** <blockquote><p>You can change the windows layout used by Vim by setting configuration variable <strong>mergetool.vimdiff.layout</strong> which accepts a string where the following separators have special meaning:</p><blockquote><p>·</p><p><strong>+</strong> is used to &quot;open a new tab&quot;</p></blockquote><blockquote><p>·</p><p><strong>,</strong> is used to &quot;open a new vertical split&quot;</p></blockquote><blockquote><p>·</p><p><strong>/</strong> is used to &quot;open a new horizontal split&quot;</p></blockquote><blockquote><p>·</p><p><strong>@</strong> is used to indicate which is the file containing the final version after solving the conflicts. If not present, <strong>MERGED</strong> will be used by default.</p></blockquote><p>The precedence of the operators is this one (you can use parentheses to change it):</p><blockquote><pre><code>\`@\` &gt; \`+\` &gt; \`/\` &gt; \`,\`
</code></pre></blockquote><p>Let&#39;s see some examples to understand how it works:</p><blockquote><p>·</p><p><strong>layout = &quot;(LOCAL,BASE,REMOTE)/MERGED&quot;</strong></p><p>This is exactly the same as the default layout we have already seen.</p><p>Note that <strong>/</strong> has precedence over <strong>,</strong> and thus the parenthesis are not needed in this case. The next layout definition is equivalent:</p><blockquote><pre><code>layout = &quot;LOCAL,BASE,REMOTE / MERGED&quot;
</code></pre></blockquote></blockquote><blockquote><p>·</p><p><strong>layout = &quot;LOCAL,MERGED,REMOTE&quot;</strong></p><p>If, for some reason, we are not interested in the <strong>BASE</strong> buffer.</p><blockquote><pre><code>------------------------------------------
|             |           |              |
|             |           |              |
|   LOCAL     |   MERGED  |   REMOTE     |
|             |           |              |
|             |           |              |
------------------------------------------
</code></pre></blockquote></blockquote><blockquote><p>·</p><p><strong>layout = &quot;MERGED&quot;</strong></p><p>Only the <strong>MERGED</strong> buffer will be shown. Note, however, that all the other ones are still loaded in vim, and you can access them with the &quot;buffers&quot; command.</p><blockquote><pre><code>------------------------------------------
|                                        |
|                                        |
|                 MERGED                 |
|                                        |
|                                        |
------------------------------------------
</code></pre></blockquote></blockquote><blockquote><p>·</p><p><strong>layout = &quot;@LOCAL,REMOTE&quot;</strong></p><p>When <strong>MERGED</strong> is not present in the layout, you must &quot;mark&quot; one of the buffers with an asterisk. That will become the buffer you need to edit and save after resolving the conflicts.</p><blockquote><pre><code>------------------------------------------
|                   |                    |
|                   |                    |
|                   |                    |
|     LOCAL         |    REMOTE          |
|                   |                    |
|                   |                    |
|                   |                    |
------------------------------------------
</code></pre></blockquote></blockquote><blockquote><p>·</p><p><strong>layout = &quot;LOCAL,BASE,REMOTE / MERGED + BASE,LOCAL + BASE,REMOTE&quot;</strong></p><p>Three tabs will open: the first one is a copy of the default layout, while the other two only show the differences between (<strong>BASE</strong> and <strong>LOCAL</strong>) and (<strong>BASE</strong> and <strong>REMOTE</strong>) respectively.</p><blockquote><pre><code>------------------------------------------
| &lt;TAB #1&gt; |  TAB #2  |  TAB #3  |       |
------------------------------------------
|             |           |              |
|   LOCAL     |   BASE    |   REMOTE     |
|             |           |              |
------------------------------------------
|                                        |
|                MERGED                  |
|                                        |
------------------------------------------
</code></pre></blockquote><blockquote><pre><code>------------------------------------------
|  TAB #1  | &lt;TAB #2&gt; |  TAB #3  |       |
------------------------------------------
|                   |                    |
|                   |                    |
|                   |                    |
|     BASE          |    LOCAL           |
|                   |                    |
|                   |                    |
|                   |                    |
------------------------------------------
</code></pre></blockquote><blockquote><pre><code>------------------------------------------
|  TAB #1  |  TAB #2  | &lt;TAB #3&gt; |       |
------------------------------------------
|                   |                    |
|                   |                    |
|                   |                    |
|     BASE          |    REMOTE          |
|                   |                    |
|                   |                    |
|                   |                    |
------------------------------------------
</code></pre></blockquote></blockquote><blockquote><p>·</p><p><strong>layout = &quot;LOCAL,BASE,REMOTE / MERGED + BASE,LOCAL + BASE,REMOTE + (LOCAL/BASE/REMOTE),MERGED&quot;</strong></p><p>Same as the previous example, but adds a fourth tab with the same information as the first tab, with a different layout.</p><blockquote><pre><code>---------------------------------------------
|  TAB #1  |  TAB #2  |  TAB #3  | &lt;TAB #4&gt; |
---------------------------------------------
|       LOCAL         |                     |
|---------------------|                     |
|       BASE          |        MERGED       |
|---------------------|                     |
|       REMOTE        |                     |
---------------------------------------------
</code></pre></blockquote><p>Note how in the third tab definition we need to use parenthesis to make <strong>,</strong> have precedence over <strong>/</strong>.</p></blockquote></blockquote><br> **Variants** <blockquote><p>Instead of <strong>--tool=vimdiff</strong>, you can also use one of these other variants:</p><blockquote><p>·</p><p><strong>--tool=gvimdiff</strong>, to open gVim instead of Vim.</p></blockquote><blockquote><p>·</p><p><strong>--tool=nvimdiff</strong>, to open Neovim instead of Vim.</p></blockquote><p>When using these variants, in order to specify a custom layout you will have to set configuration variables <strong>mergetool.gvimdiff.layout</strong> and <strong>mergetool.nvimdiff.layout</strong> instead of <strong>mergetool.vimdiff.layout</strong></p><p>In addition, for backwards compatibility with previous Git versions, you can also append <strong>1</strong>, <strong>2</strong> or <strong>3</strong> to either <strong>vimdiff</strong> or any of the variants (ex: <strong>vimdiff3</strong>, <strong>nvimdiff1</strong>, etc...) to use a predefined layout. In other words, using <strong>--tool=[g,n,]vimdiffx</strong> is the same as using <strong>--tool=[g,n,]vimdiff</strong> and setting configuration variable <strong>mergetool.[g,n,]vimdiff.layout</strong> to...</p><blockquote><p>·</p><p><strong>x=1</strong>: <strong>&quot;@LOCAL, REMOTE&quot;</strong></p></blockquote><blockquote><p>·</p><p><strong>x=2</strong>: <strong>&quot;LOCAL, MERGED, REMOTE&quot;</strong></p></blockquote><blockquote><p>·</p><p><strong>x=3</strong>: <strong>&quot;MERGED&quot;</strong></p></blockquote><p>Example: using <strong>--tool=gvimdiff2</strong> will open <strong>gvim</strong> with three columns (LOCAL, MERGED and REMOTE).</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,64))])}const b=o(a,[["render",u]]);export{d as __pageData,b as default};
